import{_ as l,b as t,e as i,a7 as e}from"./chunks/framework.CFO60l-h.js";const p=JSON.parse('{"title":"关于本站","description":"国新学伴的来源、更新、隐私、版权与联系方式。","frontmatter":{"title":"关于本站","description":"国新学伴的来源、更新、隐私、版权与联系方式。","type":"about","tags":["关于","隐私","版权"],"updated":"2026-11-07T00:00:00.000Z"},"headers":[],"relativePath":"about.md","filePath":"about.md","lastUpdated":null}'),o={name:"about.md"};function r(n,a,s,d,h,u){return t(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="关于本站" tabindex="-1">关于本站 <a class="header-anchor" href="#关于本站" aria-label="Permalink to &quot;关于本站&quot;">​</a></h1><h2 id="这是什么" tabindex="-1">这是什么 <a class="header-anchor" href="#这是什么" aria-label="Permalink to &quot;这是什么&quot;">​</a></h2><p>“国新学伴”是给中国人民大学新闻学院<strong>国际新闻与传播专业</strong>同学用的只读学习资料站。它把培养方案、课程资料、保研经验放在一个地方，并提供一个可被个人 Agent 读取的入口。</p><p>本期只做两件事：</p><ol><li><strong>查阅</strong>：培养方案、课程资料、保研资料。</li><li><strong>定制</strong>：把站点接进你自己的 Agent（复制提示词 / 上传内容包 / 安装 Skill）。</li></ol><p>本期<strong>不做</strong>上传、评论、账号、社区、排名。</p><h2 id="内容来源" tabindex="-1">内容来源 <a class="header-anchor" href="#内容来源" aria-label="Permalink to &quot;内容来源&quot;">​</a></h2><ul><li>培养方案：中国人民大学教务处《2023–2026 级本科生培养方案》大类培养方案（含辅修），页面做结构化整理并附原文 PDF。</li><li>课程资料：新闻学概论、英语新闻评论的课程阅读/范文/OP Readings；<strong>不收学生作业、成绩单、含姓名学号的个人材料</strong>。</li><li>保研资料：学院公开分享会内容（“RUC新闻一家人”公众号）、同学整理的真题/专题模板/知识框架；公开版已去除姓名与联系方式。</li><li>页面中的“回忆版/整理版”会明确标注，不会冒充官方数据。</li></ul><h2 id="更新与纠错" tabindex="-1">更新与纠错 <a class="header-anchor" href="#更新与纠错" aria-label="Permalink to &quot;更新与纠错&quot;">​</a></h2><ul><li>每页底部显示“最后更新”。</li><li>发现错误/过期/侵权，请在班级群联系站长，或填写反馈问卷。</li><li>侵权投诉 24 小时内处理；普通纠错 72 小时内处理。</li></ul><h2 id="隐私" tabindex="-1">隐私 <a class="header-anchor" href="#隐私" aria-label="Permalink to &quot;隐私&quot;">​</a></h2><ul><li>公开站不收集个人信息，不需要登录。</li><li>保研经验中的姓名、联系方式、具体去向、成绩等，公开版一律脱敏。</li><li>申请版仅限同专业同学，需人工审核，不得截图外传。</li><li>你的 Agent 可能把对话发给模型厂商；不要输入个人隐私。</li></ul><h2 id="版权" tabindex="-1">版权 <a class="header-anchor" href="#版权" aria-label="Permalink to &quot;版权&quot;">​</a></h2><ul><li>教师课件、教材、期刊论文、未公开试卷等，版权归原作者/教师/出版方；本站仅作课程学习交流，不承诺授权。</li><li>如果权利人不希望内容公开，请联系站长下架；我们会在 24 小时内处理并保留记录。</li><li>转载/引用请注明来源，不要批量搬运；不要商用。</li></ul><h2 id="免责声明" tabindex="-1">免责声明 <a class="header-anchor" href="#免责声明" aria-label="Permalink to &quot;免责声明&quot;">​</a></h2><p>本站是学习规划辅助，<strong>不替代教务系统</strong>，不做学分认定、推免资格认定、选课操作。涉及毕业、推免、评奖等关键事项，请以学院/教务处最新通知和老师答复为准。</p><h2 id="联系" tabindex="-1">联系 <a class="header-anchor" href="#联系" aria-label="Permalink to &quot;联系&quot;">​</a></h2><ul><li>站长：待填</li><li>反馈问卷：待填</li><li>申请版保研资料：待填（建议用问卷/邮箱，不要公开个人微信）</li></ul><div class="tip custom-block"><p class="custom-block-title">两天上线版</p><p>本期先保证“能打开、能查、能引用”；搜索、样式、内容会持续迭代。欢迎在班级群提问题，但请不要催更。</p></div>',19)])])}const b=l(o,[["render",r]]);export{p as __pageData,b as default};
